// Gmail'den gelen sonucu al
const items = $input.all();
const gmailResult = items[0].json;

// Google Drive sonuçlarını kontrol et
let driveFileCreated = false;
let driveFileUrl = null;

// Eğer Save to Drive? node'undan geçtiyse
const saveToDrive = $('Code in JavaScript').item.json.saveToGoogleDrive || false;

if (saveToDrive) {
  // Upload Image to Drive node'unun sonucunu kontrol et
  const uploadNode = $('Upload Image to Drive');
  const createDocNode = $('Create Report Document');

  if (uploadNode && uploadNode.item && uploadNode.item.json.webViewLink) {
    driveFileCreated = true;
    driveFileUrl = uploadNode.item.json.webViewLink;
  } else if (createDocNode && createDocNode.item && createDocNode.item.json.webViewLink) {
    driveFileCreated = true;
    driveFileUrl = createDocNode.item.json.webViewLink;
  }
}

// Flutter'ın beklediği format
return [{
  json: {
    success: true,
    emailSent: true,
    driveFileCreated: driveFileCreated,
    driveFileUrl: driveFileUrl,
    pdfGenerated: $('Code in JavaScript').item.json.generatePdf || false,
    message: driveFileCreated ? 'Email başarıyla gönderildi ve Google Drive\'a kaydedildi' : 'Email başarıyla gönderildi',
  }
}];
